// Creates a Stripe Checkout session for a Daily Stack box: one stack + optional add-ons.
// Prices come from _catalog.json (generated by _build/build.py), never from the browser.
// Needs the environment variable STRIPE_SECRET_KEY in Vercel (Settings > Environment Variables).
const CATALOG = require('./_catalog.json');

const EU = ['NL']; // Netherlands only during launch

module.exports = async (req, res) => {
  if (req.method !== 'POST') { res.setHeader('Allow', 'POST'); return res.status(405).json({ error: 'Method not allowed' }); }
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return res.status(503).json({ error: 'Checkout is not configured yet' });

  let body = req.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
  const stack = CATALOG.stacks[body && body.stack];
  if (!stack) return res.status(400).json({ error: 'Unknown stack' });
  const addons = [...new Set(Array.isArray(body.addons) ? body.addons : [])].filter(a => CATALOG.addons[a]).slice(0, 10);

  const recurring = stack.recurring;
  const p = new URLSearchParams();
  p.append('mode', recurring ? 'subscription' : 'payment');
  const items = [{ name: stack.name, amount: stack.price, desc: `${stack.count} products, every product a 30-day pack` }]
    .concat(addons.map(id => { const a = CATALOG.addons[id]; return { name: `${a.name} (${a.brand})`, amount: a.price, desc: `Extra in your box: ${a.brand} ${a.product}` }; }));
  items.forEach((it, i) => {
    p.append(`line_items[${i}][quantity]`, '1');
    p.append(`line_items[${i}][price_data][currency]`, 'eur');
    p.append(`line_items[${i}][price_data][unit_amount]`, String(it.amount));
    p.append(`line_items[${i}][price_data][tax_behavior]`, 'inclusive');
    p.append(`line_items[${i}][price_data][product_data][name]`, it.name);
    p.append(`line_items[${i}][price_data][product_data][description]`, it.desc);
    p.append(`line_items[${i}][price_data][product_data][tax_code]`, 'txcd_40090001'); // dietary supplements
    if (recurring) p.append(`line_items[${i}][price_data][recurring][interval]`, 'month');
  });
  EU.forEach(c => p.append('shipping_address_collection[allowed_countries][]', c));
  const host = req.headers['x-forwarded-host'] || req.headers.host;
  const origin = `https://${host}`;
  p.append('success_url', `${origin}/thank-you?session_id={CHECKOUT_SESSION_ID}`);
  p.append('cancel_url', `${origin}/#box`);
  p.append('allow_promotion_codes', 'true');
  p.append('billing_address_collection', 'auto');
  const meta = { stack: body.stack, addons: addons.join(',') };
  Object.entries(meta).forEach(([k, v]) => {
    p.append(`metadata[${k}]`, v);
    if (recurring) p.append(`subscription_data[metadata][${k}]`, v);
  });

  try {
    const r = await fetch('https://api.stripe.com/v1/checkout/sessions', {
      method: 'POST',
      headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/x-www-form-urlencoded' },
      body: p.toString(),
    });
    const j = await r.json();
    if (!r.ok) {
      console.error('Stripe error', j.error);
      const msg = String((j.error && j.error.message) || '').replace(/(sk|pk|rk)_(test|live)_[A-Za-z0-9*]+/g, '[key]');
      return res.status(502).json({ error: 'Payment provider error', detail: msg, code: j.error && j.error.code, param: j.error && j.error.param });
    }
    return res.status(200).json({ url: j.url });
  } catch (e) {
    console.error(e);
    return res.status(502).json({ error: 'Payment provider unreachable' });
  }
};
